// M-19: commit ve PR'larda Claude atfı yok (D-020).
import { describe, expect, it } from "vitest";
import { findAttribution, isAiIdentity } from "../../scripts/no-ai-attribution.mjs";

describe("findAttribution", () => {
  // Claude Code'un varsayılan olarak eklediği satırlar; geçmişten temizlenenler bunlardı.
  it.each([
    "Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>",
    "co-authored-by: Claude <x@example.com>",
    "Claude-Session: https://claude.ai/code/session_ORNEK",
    "🤖 Generated with [Claude Code](https://claude.com/claude-code)",
    "Generated by Claude",
    "https://claude.ai/code/session_abc",
    "  Co-Authored-By: Anthropic Bot <bot@anthropic.com>",
  ])("yakalar: %s", (line) => {
    expect(findAttribution(`Hash zincirini ekle\n\n${line}\n`)).toEqual([line]);
  });

  it.each([
    "CLAUDE.md'ye git kuralı ekle",
    "Claude Code Stop kancasını düzelt",
    "Co-Authored-By: Şerife Yılmaz <serife@example.com>",
    "Kütle dengesi toleransını %2'de tut",
  ])("geçirir: %s", (msg) => {
    expect(findAttribution(msg)).toEqual([]);
  });
});

describe("isAiIdentity", () => {
  it("Anthropic e-postası ya da Claude adı yapay zekâ kimliğidir; ekip üyeleri değildir", () => {
    expect(isAiIdentity("Claude", "noreply@anthropic.com")).toBe(true);
    expect(isAiIdentity("Claude Code", "x@example.com")).toBe(true);
    expect(isAiIdentity("Ekip Üyesi", "ekip@example.com")).toBe(false);
    expect(isAiIdentity("Claudia Demir", "claudia@example.com")).toBe(false);
  });
});
